function workflowSchedule(timezone,time,after=new Date()){
  const [hour,minute]=String(time||'09:00').split(':').map(Number),partsFor=date=>Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
  const toUtc=(parts)=>{const target=Date.UTC(parts.year,parts.month-1,parts.day,hour,minute);let guess=new Date(target);for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(guess).filter(v=>v.type!=='literal').map(v=>[v.type,Number(v.value)]));guess=new Date(guess.getTime()+target-Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute));}return guess;};
  let day=partsFor(after),scheduled=toUtc(day);if(scheduled<=after){const next=new Date(Date.UTC(day.year,day.month-1,day.day+1));day={year:next.getUTCFullYear(),month:next.getUTCMonth()+1,day:next.getUTCDate()};scheduled=toUtc(day);}return scheduled;
}
