function tokenKey(){if(!process.env.TOKEN_ENCRYPTION_KEY)throw new Error('Set TOKEN_ENCRYPTION_KEY before connecting social accounts.');return crypto.createHash('sha256').update(process.env.TOKEN_ENCRYPTION_KEY).digest();}
function encryptSecret(value){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',tokenKey(),iv),encrypted=Buffer.concat([cipher.update(String(value),'utf8'),cipher.final()]);return `${iv.toString('base64')}.${cipher.getAuthTag().toString('base64')}.${encrypted.toString('base64')}`;}
function decryptSecret(value){const [iv,tag,data]=String(value).split('.');const decipher=crypto.createDecipheriv('aes-256-gcm',tokenKey(),Buffer.from(iv,'base64'));decipher.setAuthTag(Buffer.from(tag,'base64'));return Buffer.concat([decipher.update(Buffer.from(data,'base64')),decipher.final()]).toString('utf8');}
