const publishingActive=new Set();
async function runPublishJob(job){if(publishingActive.has(job.id))return;const settings=db.prepare('SELECT stop_publishing FROM automation_settings WHERE id=1').get();if(settings?.stop_publishing)return;publishingActive.add(job.id);try{if(!['youtube','tiktok'].includes(job.social_platform))throw new Error(`${job.social_platform} publishing is not enabled yet. Connect a supported official integration or download the clip for manual upload.`);db.prepare('UPDATE publishing_jobs SET status=?,attempts=attempts+1,updated_at=? WHERE id=?').run(job.remote_id?'processing':'uploading',now(),job.id);if(job.social_platform==='youtube')await publishYoutubeJob(job);else await publishTiktokJob(job);db.prepare('INSERT INTO activity_log(id,kind,message,detail,created_at) VALUES(?,?,?,?,?)').run(id(),'publish',`${job.social_platform} publishing status updated for ${job.clip_title}`,JSON.stringify({jobId:job.id}),now());}catch(error){const status=error.needsReview?'needs_review':'failed';if(error.safeRetry)db.prepare('UPDATE publishing_jobs SET status=?,remote_id=NULL,session_url_enc=NULL,progress=0,last_error=?,updated_at=? WHERE id=?').run(status,error.message,now(),job.id);else db.prepare('UPDATE publishing_jobs SET status=?,last_error=?,updated_at=? WHERE id=?').run(status,error.message,now(),job.id);db.prepare('INSERT INTO activity_log(id,kind,message,detail,created_at) VALUES(?,?,?,?,?)').run(id(),'publish_error',`${job.social_platform} publish ${status}`,error.message,now());}finally{publishingActive.delete(job.id);}}
function tickPublisher(){const settings=db.prepare('SELECT * FROM automation_settings WHERE id=1').get();if(settings?.stop_publishing)return;db.prepare("UPDATE publishing_jobs SET status='queued' WHERE status='scheduled' AND scheduled_at<=?").run(now());const jobs=db.prepare("SELECT p.*,a.platform AS social_platform,c.title AS clip_title FROM publishing_jobs p JOIN social_accounts a ON a.id=p.social_account_id JOIN clips c ON c.id=p.clip_id WHERE p.status IN ('queued','uploading','processing') ORDER BY coalesce(p.scheduled_at,p.created_at) LIMIT 3").all();for(const job of jobs)runPublishJob(job);}
function queueWorkflowPosts(job,config){if(config.mode!=='autopilot'||!config.workflowId)return;const settings=db.prepare('SELECT * FROM automation_settings WHERE id=1').get(),workflow=db.prepare('SELECT * FROM workflows WHERE id=?').get(config.workflowId);if(!settings?.enabled||settings.stop_publishing||!workflow?.enabled)return;const rule=JSON.parse(workflow.config),accounts=rule.accountIds||[],clips=db.prepare('SELECT * FROM clips WHERE job_id=? ORDER BY created_at').all(job.id);if(!accounts.length)return;let queuedToday=db.prepare("SELECT count(*) n FROM publishing_jobs WHERE created_at>=date('now')").get().n,nextPost=new Date();const limit=Math.min(Number(rule.dailyLimit)||settings.daily_limit,settings.daily_limit);for(const clip of clips){if(clip.score<Number(rule.minimumScore||settings.minimum_score)){db.prepare('INSERT INTO activity_log(id,kind,message,detail,created_at) VALUES(?,?,?,?,?)').run(id(),'review_required',`${clip.title} sent to review: quality score below workflow threshold.`,JSON.stringify({clipId:clip.id,score:clip.score}),now());continue;}db.prepare('UPDATE clips SET approved=1 WHERE id=?').run(clip.id);for(const accountId of accounts){if(queuedToday>=limit)break;const account=db.prepare('SELECT * FROM social_accounts WHERE id=?').get(accountId);if(!account)continue;const metadata={title:clip.title,description:'',tags:[]},key=publishingIdempotencyKey(clip.id,account.id,`autopilot:${config.workflowId}`);if(db.prepare('SELECT id FROM publishing_jobs WHERE idempotency_key=?').get(key))continue;const scheduled=workflowSchedule(rule.timezone||settings.timezone,rule.scheduleTime,nextPost);nextPost=new Date(scheduled.getTime()+60_000);const postId=id(),stamp=now();db.prepare('INSERT INTO publishing_jobs(id,clip_id,social_account_id,status,scheduled_at,timezone,metadata,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)').run(postId,clip.id,account.id,'scheduled',scheduled.toISOString(),rule.timezone||settings.timezone,JSON.stringify(metadata),key,stamp,stamp);queuedToday++;}}
}
app.post('/api/projects/:projectId/jobs', (req, res) => {
  const project = db.prepare('SELECT * FROM projects WHERE id=?').get(req.params.projectId);
  if (!project || !project.source_path) return res.status(404).json({ error: 'Project source is unavailable.' });
  const running = db.prepare("SELECT id FROM jobs WHERE project_id=? AND status IN ('queued','processing')").get(project.id);
  if (running) return res.status(409).json({ error: 'This project already has a generation job running.' });
  const { count='5', length=35, aspect='9:16', category='Highlights', platform='Any platform', instruction='', mode='review' } = req.body || {};
  const config = { count: count === 'auto' ? 'auto' : Math.max(1, Math.min(50, Number(count) || 5)), length: Math.max(10,Math.min(90,Number(length)||35)), aspect, category, platform, instruction: String(instruction).slice(0,500), mode };
  const jobId = id(), stamp=now();
  db.prepare('INSERT INTO jobs(id,project_id,status,stage,progress,config,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(jobId, project.id, 'queued', 'Waiting for worker', 0, JSON.stringify(config), stamp, stamp);
  processJob(db.prepare('SELECT * FROM jobs WHERE id=?').get(jobId));
  res.status(202).json({ id: jobId, project_id: project.id, status: 'queued', stage: 'Waiting for worker', progress: 0, config });
});
