app.get('/api/accounts/:id/publishing-options',async(req,res)=>{const account=db.prepare('SELECT * FROM social_accounts WHERE id=?').get(req.params.id);if(!account)return res.status(404).json({error:'Account not found.'});if(account.platform==='youtube')return res.json({privacyOptions:['public','unlisted','private']});if(account.platform==='tiktok'){try{const token=await tiktokAccessToken(account),r=await fetch('https://open.tiktokapis.com/v2/post/publish/creator_info/query/',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:'{}'}),d=await r.json();if(!r.ok||d.error?.code!=='ok')throw new Error(d.error?.message||'Could not read TikTok creator publishing options.');return res.json({privacyOptions:d.data.privacy_level_options||[],maxVideoDurationSeconds:d.data.max_video_post_duration_sec||null});}catch(e){return res.status(502).json({error:e.message});}}res.status(501).json({error:'Publishing options are not implemented for this platform.'});});
app.get('/api/publishing', (_req,res) => {const items=db.prepare('SELECT p.*,c.title AS clip_title,a.platform,a.display_name AS account_name FROM publishing_jobs p JOIN clips c ON c.id=p.clip_id JOIN social_accounts a ON a.id=p.social_account_id ORDER BY coalesce(p.scheduled_at,p.created_at) DESC').all().map(({session_url_enc,...j})=>({...j,metadata:JSON.parse(j.metadata)}));const settings=db.prepare('SELECT * FROM automation_settings WHERE id=1').get();res.json({items,stopPublishing:Boolean(settings.stop_publishing),settings});});
app.post('/api/publishing',(req,res)=>{const {clipId,accountId,title,description='',tags=[],scheduledAt=null,timezone='UTC',privacy='public'}=req.body||{};const clip=db.prepare('SELECT * FROM clips WHERE id=?').get(clipId),account=db.prepare('SELECT * FROM social_accounts WHERE id=?').get(accountId);if(!clip||!account)return res.status(404).json({error:'Select a ready clip and connected destination account.'});if(!clip.approved)return res.status(409).json({error:'Approve the clip in Review mode before publishing.'});const privacyAllowed=account.platform==='tiktok'?['PUBLIC_TO_EVERYONE','MUTUAL_FOLLOW_FRIENDS','FOLLOWER_OF_CREATOR','SELF_ONLY'].includes(privacy):['public','unlisted','private'].includes(privacy);if(!privacyAllowed)return res.status(400).json({error:'Choose a visibility level supported by the selected destination.'});let date=null;if(scheduledAt){const ms=Date.parse(scheduledAt);if(!Number.isFinite(ms)||ms<Date.now())return res.status(400).json({error:'Choose a future schedule time.'});date=new Date(ms).toISOString();}const metadata={title:String(title||clip.title).slice(0,100),description:String(description).slice(0,5000),tags:Array.isArray(tags)?tags.map(String).slice(0,30):[]},key=publishingIdempotencyKey(clip.id,account.id,date||'immediate'),existing=db.prepare('SELECT * FROM publishing_jobs WHERE idempotency_key=?').get(key);if(existing)return res.status(200).json(existing);const jobId=id(),stamp=now(),status=date?'scheduled':'queued';db.prepare('INSERT INTO publishing_jobs(id,clip_id,social_account_id,status,scheduled_at,timezone,metadata,privacy_status,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(jobId,clip.id,account.id,status,date,timezone,JSON.stringify(metadata),privacy,key,stamp,stamp);db.prepare('INSERT INTO activity_log(id,kind,message,detail,created_at) VALUES(?,?,?,?,?)').run(id(),'publish_queued',`${clip.title} queued for ${account.display_name}`,JSON.stringify({jobId,platform:account.platform,scheduledAt:date}),stamp);res.status(202).json(db.prepare('SELECT * FROM publishing_jobs WHERE id=?').get(jobId));});
app.post('/api/publishing/:id/retry',(req,res)=>{const job=db.prepare('SELECT * FROM publishing_jobs WHERE id=?').get(req.params.id);if(!job)return res.status(404).json({error:'Publishing job not found.'});if(job.status==='needs_review')return res.status(409).json({error:'The remote outcome is uncertain. Check the destination account before any retry to prevent duplicate posts.'});if(!['failed','published'].includes(job.status))return res.status(409).json({error:'Only failed or completed status checks can be retried.'});db.prepare('UPDATE publishing_jobs SET status=?,last_error=NULL,updated_at=? WHERE id=?').run(job.remote_id?'processing':'queued',now(),job.id);tickPublisher();res.json({ok:true});});
app.post('/api/settings/stop-publishing',(req,res)=>{const stop=req.body?.stop===false?0:1;db.prepare('UPDATE automation_settings SET stop_publishing=?,updated_at=? WHERE id=1').run(stop,now());db.prepare('INSERT INTO activity_log(id,kind,message,created_at) VALUES(?,?,?,?)').run(id(),'stop_publishing',stop?'Global stop publishing enabled':'Global stop publishing disabled',now());res.json({stopPublishing:Boolean(stop)});});
app.get('/api/settings/automation',(_req,res)=>res.json(db.prepare('SELECT * FROM automation_settings WHERE id=1').get()));
app.put('/api/settings/automation',(req,res)=>{const body=req.body||{},enabled=body.enabled?1:0,daily=Math.max(1,Math.min(50,Number(body.daily_limit)||3)),score=Math.max(0,Math.min(100,Number(body.minimum_score)||0)),timezone=String(body.timezone||'UTC').slice(0,60);db.prepare('UPDATE automation_settings SET enabled=?,daily_limit=?,minimum_score=?,timezone=?,updated_at=? WHERE id=1').run(enabled,daily,score,timezone,now());res.json(db.prepare('SELECT * FROM automation_settings WHERE id=1').get());});
app.get('/api/workflows',(_req,res)=>res.json(db.prepare('SELECT * FROM workflows ORDER BY created_at DESC').all().map(w=>({...w,config:JSON.parse(w.config)}))));
app.post('/api/workflows',(req,res)=>{const body=req.body||{},timezone=String(body.timezone||'UTC'),scheduleTime=String(body.scheduleTime||'09:00');try{new Intl.DateTimeFormat('en-US',{timeZone:timezone});}catch{return res.status(400).json({error:'Provide a valid IANA timezone for the workflow schedule.'});}if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(scheduleTime))return res.status(400).json({error:'Set the workflow posting time in 24-hour HH:MM format.'});const config={count:body.count==='auto'?'auto':Math.max(1,Math.min(50,Number(body.count)||5)),length:Math.max(10,Math.min(90,Number(body.length)||35)),aspect:['9:16','1:1','4:5','16:9'].includes(body.aspect)?body.aspect:'9:16',category:String(body.category||'Highlights').slice(0,40),instruction:String(body.instruction||'').slice(0,500),accountIds:Array.isArray(body.accountIds)?body.accountIds.filter(x=>db.prepare('SELECT id FROM social_accounts WHERE id=?').get(x)):[],dailyLimit:Math.max(1,Math.min(50,Number(body.dailyLimit)||3)),minimumScore:Math.max(0,Math.min(100,Number(body.minimumScore)||0)),timezone,scheduleTime,captionStyle:['clean','bold','minimal'].includes(body.captionStyle)?body.captionStyle:'clean',captionPosition:['top','center','bottom'].includes(body.captionPosition)?body.captionPosition:'bottom'};const workflowId=id(),stamp=now();db.prepare('INSERT INTO workflows(id,name,enabled,config,created_at,updated_at) VALUES(?,?,?,?,?,?)').run(workflowId,String(body.name||'My workflow').slice(0,80),body.enabled?1:0,JSON.stringify(config),stamp,stamp);res.status(201).json({id:workflowId,name:String(body.name||'My workflow'),enabled:Boolean(body.enabled),config});});
app.put('/api/workflows/:id',(req,res)=>{const workflow=db.prepare('SELECT * FROM workflows WHERE id=?').get(req.params.id);if(!workflow)return res.status(404).json({error:'Workflow not found.'});const enabled=req.body?.enabled===undefined?workflow.enabled:(req.body.enabled?1:0),name=String(req.body?.name||workflow.name).slice(0,80);db.prepare('UPDATE workflows SET enabled=?,name=?,updated_at=? WHERE id=?').run(enabled,name,now(),workflow.id);res.json({ok:true});});
app.delete('/api/workflows/:id',(req,res)=>{const result=db.prepare('DELETE FROM workflows WHERE id=?').run(req.params.id);if(!result.changes)return res.status(404).json({error:'Workflow not found.'});res.json({ok:true});});
app.post('/api/workflows/:id/run',(req,res)=>{const workflow=db.prepare('SELECT * FROM workflows WHERE id=?').get(req.params.id),project=db.prepare('SELECT * FROM projects WHERE id=?').get(req.body?.projectId);if(!workflow||!project?.source_path)return res.status(404).json({error:'Select a workflow and project with a ready source.'});const existing=db.prepare("SELECT id FROM jobs WHERE project_id=? AND status IN ('queued','processing')").get(project.id);if(existing)return res.status(409).json({error:'A generation job is already running for this project.'});const c=JSON.parse(workflow.config),config={...c,mode:'autopilot',workflowId:workflow.id},jobId=id(),stamp=now();db.prepare('INSERT INTO jobs(id,project_id,status,stage,progress,config,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(jobId,project.id,'queued','Workflow queued',0,JSON.stringify(config),stamp,stamp);processJob(db.prepare('SELECT * FROM jobs WHERE id=?').get(jobId));res.status(202).json({id:jobId,status:'queued'});});
app.get('/api/review-queue',(_req,res)=>res.json(db.prepare('SELECT c.id,c.title,c.start,c.duration,c.score,c.reason,p.name AS project_name FROM clips c JOIN projects p ON p.id=c.project_id WHERE c.approved=0 ORDER BY c.created_at DESC').all()));
app.get('/api/activity',(_req,res)=>res.json(db.prepare('SELECT * FROM activity_log ORDER BY created_at DESC LIMIT 200').all()));
app.use((err,_req,res,_next)=>{ console.error(err); res.status(500).json({error:err.message || 'Server error'}); });
const port=Number(process.env.PORT||3001);
app.listen(port, process.env.HOST || '127.0.0.1', ()=>console.log(`Splice Studio API listening on 127.0.0.1:${port}; data in ${dataDir}`));
const publisherTimer=setInterval(tickPublisher,5000);publisherTimer.unref();tickPublisher();
// Requeue interrupted jobs after a restart. Rendering starts from scratch; completed clips remain persisted.
for (const job of db.prepare("SELECT * FROM jobs WHERE status IN ('queued','processing')").all()) { updateJob(job.id,{status:'queued',stage:'Resuming after server restart'}); processJob(db.prepare('SELECT * FROM jobs WHERE id=?').get(job.id)); }
for (const imp of db.prepare("SELECT * FROM imports WHERE status IN ('queued','importing')").all()) { db.prepare('UPDATE imports SET status=? WHERE id=?').run('queued',imp.id); processImport(db.prepare('SELECT * FROM imports WHERE id=?').get(imp.id)); }
